import { NextResponse, type NextRequest } from "next/server";
import { ACCESS_COOKIE, REFRESH_COOKIE } from "./config";
import { makeErrorShape } from "./error";

/** Error response in the standard format, generated by the BFF itself. */
export function errorResponse(statusCode: number, code: string, message: string, path: string) {
  return NextResponse.json(makeErrorShape(statusCode, code, message, path), {
    status: statusCode,
    headers: { "cache-control": "no-store" },
  });
}

/** CSRF defense in depth (cookies are already SameSite=Lax): unsafe methods must come from this origin. */
export function assertSameOrigin(request: NextRequest, path: string): NextResponse | null {
  if (["GET", "HEAD", "OPTIONS"].includes(request.method)) return null;

  const origin = request.headers.get("origin");
  if (!origin) return null; // non-browser clients / same-origin navigations without Origin

  const host = request.headers.get("x-forwarded-host") ?? request.headers.get("host");
  try {
    if (new URL(origin).host === host) return null;
  } catch {
    /* fallthrough */
  }
  return errorResponse(403, "FORBIDDEN", "درخواست از مبدا نامعتبر ارسال شده است.", path);
}

export function clearAuthCookies(res: NextResponse) {
  res.cookies.delete(ACCESS_COOKIE);
  res.cookies.delete(REFRESH_COOKIE);
  return res;
}
